(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+y)*0.01+t*0.5)*8+Math.cos((x-y)*0.012-t*0.4)*6;
  wy += Math.cos((x+y)*0.011-t*0.45)*8+Math.sin((x-y)*0.009+t*0.55)*6;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.2],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.5],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,5.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+4)*50,0.11,2.1,4.3],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75)*40,0.085,1.8,1.9]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    mS+=Math.sin(d*f*1.3-t*sp*0.4+ph*2)*0.6;
  }
  const act=aS/8,inh=iS/8,mut=mS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07*Math.cos(t*0.3)+sy*0.05*Math.sin(t*0.4)+t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08+ang*2-t*0.8)*0.15;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const diff=act-inh,lap=mut*0.4+Math.sin(sx*0.2+sy*0.2+t*3)*0.2;
  const rd2=Math.tanh((diff+lap+bg*0.15)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.4+t*4)*Math.sin(sy*0.35-t*3.5)*0.08;
  const blend=rd1*0.5+rd2*0.25+cell*0.15+micro, v=blend*0.5+0.5;
  const pal=[
    [5,12,45],[12,45,85],[18,85,115],[25,140,135],[55,175,145],
    [145,195,120],[210,190,80],[220,145,65],[195,85,75],
    [155,50,70],[95,25,65],[45,15,55],[5,12,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(rd1*Math.PI)*0.15+Math.abs(rd2)*0.1;
  const edge=Math.abs(rd1)>0.65?1.2:Math.abs(rd2)>0.5?1.1:1.0;
  const glow=Math.max(0,1-dist/220)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*20)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*40)|0)
  ];
}
